import numpy as np

def is_separated(p1, p2, lines):
    for a, b, c in lines:
        if (a * p1[0] + b * p1[1] + c) * (a * p2[0] + b * p2[1] + c) < 0:
            return True
    return False

def check_goal(red_points, blue_points, lines):
    for r in red_points:
        for b in blue_points:
            if not is_separated(r, b, lines):
                return False
    return True

reds = [(0, 0), (10, 0)]
blues = [(-1, -1), (1, -1), (0, 1), (9, -1), (11, -1), (10, 1)]

# L2 is almost the line R1R2
# L1 isolates R1, L3 isolates R2
# L2: y = 0.01
# L1: x - 100*y = 0.01  => x - 100y - 0.01 = 0
# L3: x + 100*y = 1000.01 => x + 100y - 1000.01 = 0
lines = [(0, 1, -0.01), (1, -100, -0.01), (1, 100, -1000.01)]

print(f"Check goal: {check_goal(reds, blues, lines)}")
